describe('908278 - Pasted Ordered List Inherits Parent Element’s OL Tag in Rich Text Editor', () => {
    let rteObj: RichTextEditor;
    let keyBoardEvent: any = {
        preventDefault: () => { },
        type: 'keydown',
        stopPropagation: () => { },
        ctrlKey: false,
        shiftKey: false,
        action: null,
        which: 64,
        key: ''
    };
    beforeAll((done: Function) => {
        const ol = document.createElement('ol');
        const li = document.createElement('li');
        ol.appendChild(li);
        const root: HTMLElement = createElement('div', {className: 'custom'});
        li.appendChild(root);
        document.body.appendChild(ol);
        rteObj = new RichTextEditor({
                pasteCleanupSettings: {
                    prompt: true
                },
                value: ''
        }, root);
        done();
    });
    it('Pasted Ordered List Inherits Parent Element’s OL Tag in Rich Text Editor', (done) => {
        const localElem: string = `<ol><li>HELLO</li><li>HI</li><li>BYE</li></ol>`;
        rteObj.value = '<p><br></p>';
        rteObj.dataBind();
        keyBoardEvent.clipboardData = {
            getData: () => {
                return localElem;
            },
            items: []
        };
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        rteObj.onPaste(keyBoardEvent);
        setTimeout(() => {
            if (rteObj.pasteCleanupSettings.prompt) {
                let keepFormat: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_KEEP_FORMAT);
                keepFormat[0].click();
                let pasteOK: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_OK);
                pasteOK[0].click();
            }
            let pastedElem: string = (rteObj as any).inputElement.innerHTML;
            let expected: boolean = true;
            let expectedElem: string = `<ol><li>HELLO</li><li>HI</li><li>BYE</li></ol>`;
            if (pastedElem !== expectedElem) {
                expected = false;
            }
            (rteObj as any).inputElement.blur();
            expect(expected).toBe(true);
            done();
        }, 100);
    });
    afterAll((done: DoneFn) => {
        destroy(rteObj);
        done();
    });
});

describe('Bug 1031477: Table width Shrink Automatically When Pasting from Word into Syncfusion Rich Text Editor', () => {
    let rteObj: RichTextEditor;

    beforeEach(() => {
        rteObj = renderRTE({
            pasteCleanupSettings: {
                prompt: false
            },
            value: '<p><br></p>'
        });
    });

    it('Table with width:0 style should have width removed after paste', (done) => {
        const localElem: string = `<html xmlns:o="urn:schemas-microsoft-com:office:office"
xmlns:w="urn:schemas-microsoft-com:office:word"
xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta http-equiv=Content-Type content="text/html; charset=utf-8">
<meta name=ProgId content=Word.Document>
<meta name=Generator content="Microsoft Word 15">
<style>
<!--
table.MsoNormalTable
{mso-style-name:"Table Normal";
mso-tstyle-rowband-size:0;
mso-tstyle-colband-size:0;
mso-style-noshow:yes;
mso-style-priority:99;
mso-style-parent:"";
mso-padding-alt:0in 5.4pt 0in 5.4pt;
mso-para-margin-top:0in;
mso-para-margin-right:0in;
mso-para-margin-bottom:8.0pt;
mso-para-margin-left:0in;}
-->
</style>
</head>
<body>
<!--StartFragment-->
<p class="MsoNormal"><table style="width:0"><tr><td class="MsoNormal">Cell 1</td><td class="MsoNormal">Cell 2</td></tr></table><o:p></o:p></p>
<!--EndFragment-->
</body>
</html>`;
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', localElem);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            const tableElement: HTMLElement = rteObj.inputElement.querySelector('table');
            const tableStyle: string = tableElement.getAttribute('style');
            expect(tableStyle).toBeNull();
            done();
        }, 100);
    });

    it('Table with width:0px style should have width removed after paste', (done) => {
        const localElem: string = `<html xmlns:o="urn:schemas-microsoft-com:office:office"
xmlns:w="urn:schemas-microsoft-com:office:word"
xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta http-equiv=Content-Type content="text/html; charset=utf-8">
<meta name=ProgId content=Word.Document>
<meta name=Generator content="Microsoft Word 15">
<style>
<!--
table.MsoNormalTable
{mso-style-name:"Table Normal";
mso-style-noshow:yes;
mso-style-priority:99;
mso-padding-alt:0in 5.4pt 0in 5.4pt;}
-->
</style>
</head>
<body>
<!--StartFragment-->
<p class="MsoNormal"><table style="width:0px"><tr><td class="MsoNormal">Cell 1</td><td class="MsoNormal">Cell 2</td></tr></table><o:p></o:p></p>
<!--EndFragment-->
</body>
</html>`;
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', localElem);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            const tableElement: HTMLElement = rteObj.inputElement.querySelector('table');
            const tableStyle: string = tableElement.getAttribute('style');
            expect(tableStyle).toBeNull();
            done();
        }, 100);
    });

    it('Table with other styles along with width:0 should preserve other styles', (done) => {
        const localElem: string = `<html xmlns:o="urn:schemas-microsoft-com:office:office"
xmlns:w="urn:schemas-microsoft-com:office:word"
xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta http-equiv=Content-Type content="text/html; charset=utf-8">
<meta name=ProgId content=Word.Document>
<meta name=Generator content="Microsoft Word 15">
<style>
<!--
table.MsoNormalTable
{mso-style-name:"Table Normal";
mso-style-noshow:yes;
mso-style-priority:99;
mso-padding-alt:0in 5.4pt 0in 5.4pt;}
-->
</style>
</head>
<body>
<!--StartFragment-->
<p class="MsoNormal"><table style="border:none;width:0"><tr><td class="MsoNormal">Cell 1</td></tr></table><o:p></o:p></p>
<!--EndFragment-->
</body>
</html>`;
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', localElem);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            const tableElement: HTMLElement = rteObj.inputElement.querySelector('table');
            const tableStyle: string = tableElement.getAttribute('style');
            expect(tableStyle).toBe('border:none;');
            done();
        }, 100);
    });

    afterEach(() => {
        destroy(rteObj);
    });
});

