describe('Bug 1030056: Loss of Double Borders When Pasting Tables from Word into RichTextEditor', () => {
    let rteObj: RichTextEditor;

    beforeAll(() => {
        rteObj = renderRTE({
            pasteCleanupSettings: {
                prompt: true,
                allowedStyleProps: ['background', 'background-color', 'border', 'border-bottom', 'border-left', 'border-radius', 'border-right', 'border-style', 'border-top', 'border-width', 'clear', 'color', 'cursor', 'direction', 'display', 'float', 'font', 'font-family', 'font-size', 'font-weight', 'font-style', 'height', 'left', 'line-height', 'list-style-type', 'margin', 'margin-top', 'margin-left', 'margin-right', 'margin-bottom', 'max-height', 'max-width', 'min-height', 'min-width', 'overflow', 'overflow-x', 'overflow-y', 'padding', 'padding-bottom', 'padding-left', 'padding-right', 'padding-top', 'position', 'right', 'table-layout', 'text-align', 'text-decoration', 'text-transform', 'text-indent', 'top', 'vertical-align', 'visibility', 'white-space', 'width', 'flex-direction', 'border-collapse', 'border-spacing'],
            },
            value: '<p><br></p>'
        });
    });

    it('Table with mso-cellspacing should have border-collapse: separate and border-spacing after paste', (done) => {
        // Table HTML with mso-cellspacing style that matches the regex pattern /mso-cellspacing\s*:\s*([^;]+);?/i
        const localElem: string = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office"
        xmlns:w="urn:schemas-microsoft-com:office:word"
        xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"
        xmlns:v="urn:schemas-microsoft-com:vml"
        xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessing"
        xmlns:ms="urn:schemas-microsoft-com:office:word">
        <head>
        <meta http-equiv="Content-Type" content="text/html; charset=utf-8">
        <meta name="Generator" content="Microsoft Word 15">
        <style>
        table
            {mso-displayed-decimal-separator:"\\.";
            mso-displayed-thousand-separator:"\\,";}
        </style>
        </head>
        <body>
        <table style="mso-cellspacing:2.0pt;border-collapse:separate;border-spacing:2.0pt;">
        <tbody>
            <tr>
                <td style="padding:6.75pt 6.75pt 6.75pt 6.75pt;">Cell 1</td>
                <td style="padding:6.75pt 6.75pt 6.75pt 6.75pt;">Cell 2</td>
            </tr>
            <tr>
                <td style="padding:6.75pt 6.75pt 6.75pt 6.75pt;">Cell 3</td>
                <td style="padding:6.75pt 6.75pt 6.75pt 6.75pt;">Cell 4</td>
            </tr>
        </tbody>
        </table>
        </body>
        </html>
        `;
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', localElem);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            if (rteObj.pasteCleanupSettings.prompt) {
                let keepFormat: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_KEEP_FORMAT);
                keepFormat[0].click();
                let pasteOK: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_OK);
                pasteOK[0].click();
            }
            const table: HTMLTableElement = rteObj.inputElement.querySelector('table');
            expect(table).not.toBeNull();
            // Verify border-collapse: separate is applied
            expect(table.style.borderCollapse).toBe('separate');
            // Verify border-spacing is applied with the value from mso-cellspacing
            expect(table.style.borderSpacing).toBe('2pt');
            done();
        }, 100);
    });

    afterAll(() => {
        destroy(rteObj);
    });
});

describe('Bug 1030056: Loss of Double Borders When Pasting Tables from Word into RichTextEditor', () => {
    let rteObj: RichTextEditor;
    let editNode: HTMLElement;

    beforeEach(() => {
        rteObj = renderRTE({
            pasteCleanupSettings: {
                prompt: false
            },
            value: '<p><br></p>'
        });
    });

    afterEach(() => {
        destroy(rteObj);
    });

    function setRangeAtStartOfLastCell(): void {
        const lastCell: HTMLTableCellElement = editNode.querySelector('table').rows[1].cells[1];
        const range: Range = document.createRange();
        range.setStart(lastCell, 0);
        range.setEnd(lastCell, 0);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
    }

    it('Should return null when cursor is only at the beginning of last cell (not entire selection)', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        setRangeAtStartOfLastCell();
        const pasteHtml: string = '<span>Partial Insert</span>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table should still exist (not entire table selection)
            const table: HTMLTableElement = editNode.querySelector('table');
            expect(table).not.toBeNull();
            // The table should remain, content should be inserted before it
            done();
        }, 100);
    });

    it('Should use element node path in isRangeEndAtLastCellEnd when range.endContainer is element', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const lastCell: HTMLTableCellElement = table.rows[1].cells[1];
        // Create range with endContainer as element node (lastCell itself)
        const range: Range = document.createRange();
        range.setStart(table.rows[0].cells[0], 0);
        range.setEnd(lastCell, lastCell.childNodes.length); // endOffset = childNodes.length
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<div>Full Replace</div>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Entire table should be replaced (end at last cell element with offset = length)
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).toBeNull();
            done();
        }, 100);
    });

    it('Should detect entire table selection when start in first cell and end in last cell with TEXT_NODE path', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const firstTextNode: Text = (table.rows[0].cells[0]).firstChild as Text;
        const lastTextNode: Text = (table.rows[1].cells[1]).firstChild as Text;
        // Full range with text nodes
        const range: Range = document.createRange();
        range.setStart(firstTextNode, 0);
        range.setEnd(lastTextNode, lastTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<p>Replaced Table</p>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).toBeNull();
            done();
        }, 100);
    });

    it('Should return null when end is at last cell text end but there is content after text node within cell', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4<span>extra</span></td></tr></tbody></table><p><br></p>';
        // In this case, hasContentAfterNode should return true because there's a <span> after text
        const table: HTMLTableElement = editNode.querySelector('table');
        const lastCell: HTMLTableCellElement = table.rows[1].cells[1];
        const lastTextNode: Text = lastCell.firstChild as Text;
        // Range ends at absolute end of text node, but there's an element sibling after
        const range: Range = document.createRange();
        range.setStart(table.rows[0].cells[0], 0);
        range.setEnd(lastTextNode, lastTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<span>Content</span>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table should still exist because hasContentAfterNode returns true
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).not.toBeNull();
            done();
        }, 100);
    });

    it('Should return null when start is at first cell but end is at last cell AND there is intervening content after container', (done) => {
        editNode = (rteObj as any).inputElement;
        // Use isContainerAtOrAfterLastCell path with intervening content
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const lastCell: HTMLTableCellElement = table.rows[1].cells[1];
        // Range with endContainer = lastCell element (element path), but with content after inside
        const range: Range = document.createRange();
        range.setStart(table.rows[0].cells[0], 0);
        // endContainer is lastCell, offset at length - but container is not after last cell content (has content)
        const tempSpan: HTMLElement = document.createElement('span');
        lastCell.appendChild(tempSpan);
        range.setEnd(lastCell, lastCell.childNodes.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<span>Inserted</span>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table should still be there since tempSpan was appended (hasContentAfterNode true)
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).not.toBeNull();
            done();
        }, 100);
    });

    it('Should return null when endCell is not the last cell (not allCells[allCells.length - 1])', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        // Place cursor at end of second-to-last cell (Cell 3 in row 2, col 1 - not the last cell)
        const middleCell: HTMLTableCellElement = table.rows[1].cells[0];
        const middleTextNode: Text = middleCell.firstChild as Text;
        const range: Range = document.createRange();
        // Start at beginning of first cell
        range.setStart(table.rows[0].cells[0], 0);
        // End at middle of table (not last cell)
        range.setEnd(middleTextNode, middleTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<div>Partial Table Insert</div>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table should still exist since range doesn't end at last cell
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).not.toBeNull();
            done();
        }, 100);
    });

    it('Should return null when start and end are in same table but start is not at first cell', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const startCell: HTMLTableCellElement = table.rows[1].cells[0]; // Start at Cell 3 (not first cell)
        const endTextNode: Text = (table.rows[1].cells[1]).firstChild as Text;
        const range: Range = document.createRange();
        range.setStart(startCell, 0);
        range.setEnd(endTextNode, endTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<span>Middle Insert</span>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table should remain since startCell !== allCells[0]
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).not.toBeNull();
            done();
        }, 100);
    });

    it('Should apply e-entire-table-selected class when entire table is selected', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Cell 1</td><td>Cell 2</td></tr><tr><td>Cell 3</td><td>Cell 4</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const firstTextNode: Text = (table.rows[0].cells[0]).firstChild as Text;
        const lastTextNode: Text = (table.rows[1].cells[1]).firstChild as Text;
        const range: Range = document.createRange();
        range.setStart(firstTextNode, 0);
        range.setEnd(lastTextNode, lastTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        // Just trigger paste without clipboard data to observe the selection marker
        // The class is added before paste content is processed
        const pasteHtml: string = '<div>Test</div>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // After paste, table should be removed (replaced)
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).toBeNull();
            done();
        }, 100);
    });

    it('Should handle nested table cells (th elements) correctly in entire table detection', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><thead><tr><th>Header 1</th><th>Header 2</th></tr></thead><tbody><tr><td>Data 1</td><td>Data 2</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const firstHeader: HTMLElement = table.querySelector('th');
        const lastCell: HTMLTableCellElement = table.rows[1].cells[1];
        const lastTextNode: Text = lastCell.firstChild as Text;
        const range: Range = document.createRange();
        range.setStart(firstHeader, 0);
        range.setEnd(lastTextNode, lastTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<p>Header Table Replaced</p>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            // Table with th should also be detected as entire table selection
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).toBeNull();
            done();
        }, 100);
    });

    it('Should handle multi-row single column table entire selection', (done) => {
        editNode = (rteObj as any).inputElement;
        editNode.innerHTML = '<table border="1"><tbody><tr><td>Row 1</td></tr><tr><td>Row 2</td></tr><tr><td>Row 3</td></tr></tbody></table><p><br></p>';
        const table: HTMLTableElement = editNode.querySelector('table');
        const firstCell: HTMLTableCellElement = table.rows[0].cells[0];
        const lastCell: HTMLTableCellElement = table.rows[2].cells[0];
        const lastTextNode: Text = lastCell.firstChild as Text;
        const range: Range = document.createRange();
        range.setStart(firstCell, 0);
        range.setEnd(lastTextNode, lastTextNode.textContent.length);
        const selection: Selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        const pasteHtml: string = '<div>Single Column Table Replaced</div>';
        const dataTransfer: DataTransfer = new DataTransfer();
        dataTransfer.setData('text/html', pasteHtml);
        const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
        rteObj.contentModule.getEditPanel().dispatchEvent(pasteEvent);
        setTimeout(() => {
            const tableEl: HTMLTableElement = editNode.querySelector('table');
            expect(tableEl).toBeNull();
            done();
        }, 100);
    });
});

